package com.universe.community.service; import com.universe.community.dto.request.*; import com.universe.community.dto.response.CommentResponse; import com.universe.community.entity.*; import com.universe.community.repository.*; import com.universe.global.common.PageResponse; import com.universe.global.exception.*; import com.universe.global.security.CurrentUser; import com.universe.user.repository.UserRepository; import com.universe.notification.event.CommentCreatedEvent; import lombok.RequiredArgsConstructor; import org.springframework.context.ApplicationEventPublisher; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class CommentService {private final CommentRepository comments;private final CommunityPostRepository posts;private final UserRepository users;private final ApplicationEventPublisher events; @Transactional(readOnly=true) public PageResponse<CommentResponse> list(Long postId,int page,int size){post(postId);var p=comments.findByPostIdAndStatusOrderByCreatedAtAsc(postId,PostStatus.ACTIVE,PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100)));return new PageResponse<>(p.map(CommentResponse::from));} @Transactional public CommentResponse create(Long postId,CommentCreateRequest r){var p=post(postId);var u=user();Comment parent=null;if(r.getParentCommentId()!=null){parent=comments.findByIdAndStatus(r.getParentCommentId(),PostStatus.ACTIVE).orElseThrow(()->new BusinessException(ErrorCode.PARENT_COMMENT_NOT_FOUND));if(!parent.getPost().getId().equals(postId))throw new BusinessException(ErrorCode.PARENT_COMMENT_NOT_FOUND);}var saved=comments.save(Comment.builder().post(p).user(u).parentComment(parent).content(r.getContent()).isAnonymous(r.getIsAnonymous()).build());events.publishEvent(new CommentCreatedEvent(postId,p.getTitle(),p.getUser().getId(),u.getId(),parent==null?null:parent.getUser().getId()));return CommentResponse.from(saved);} @Transactional public CommentResponse update(Long id,CommentUpdateRequest r){var c=comments.findByIdAndStatus(id,PostStatus.ACTIVE).orElseThrow(()->new BusinessException(ErrorCode.COMMENT_NOT_FOUND));if(!c.getUser().getId().equals(CurrentUser.id()))throw new BusinessException(ErrorCode.FORBIDDEN);c.updateContent(r.getContent(),r.getIsAnonymous());return CommentResponse.from(c);} @Transactional public void delete(Long id){var c=comments.findByIdAndStatus(id,PostStatus.ACTIVE).orElseThrow(()->new BusinessException(ErrorCode.COMMENT_NOT_FOUND));if(!c.getUser().getId().equals(CurrentUser.id()))throw new BusinessException(ErrorCode.FORBIDDEN);c.deleteComment();} private CommunityPost post(Long id){var p=posts.findByIdAndStatus(id,PostStatus.ACTIVE).orElseThrow(()->new BusinessException(ErrorCode.POST_NOT_FOUND));var u=user();if(u.getSchool()==null||!u.getSchool().getId().equals(p.getSchool().getId()))throw new BusinessException(ErrorCode.CROSS_SCHOOL_ACCESS);return p;} private com.universe.user.entity.User user(){return users.findById(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHORIZED));}}
